// Logos drawn in black or near-black, shown inverted (keeping their hue) in the dark theme.
const DARK = new Set(["actix", "bash", "containerd", "deno", "django", "expo", "express", "flask", "influxdb", "mariadb", "ollama", "remix", "rust", "symfony", "tailscale"]);

const PROCESSES = {"nginx": "nginx", "openresty": "nginx", "apache2": "apache", "httpd": "apache", "caddy": "caddy", "traefik": "traefik", "envoy": "envoy", "postgres": "postgresql", "postmaster": "postgresql", "mysqld": "mysql", "mariadbd": "mariadb", "mongod": "mongodb", "mongos": "mongodb", "redis-server": "redis", "memcached": "memcached", "clickhouse-server": "clickhouse", "clickhouse": "clickhouse", "cockroach": "cockroachdb", "influxd": "influxdb", "etcd": "etcd", "neo4j": "neo4j", "cassandra": "cassandra", "rabbitmq-server": "rabbitmq", "nats-server": "nats", "minio": "minio", "meilisearch": "meilisearch", "qdrant": "qdrant", "surreal": "surrealdb", "dockerd": "docker", "docker-proxy": "docker", "com.docker.backend": "docker", "docker": "docker", "containerd": "containerd", "podman": "podman", "kubelet": "kubernetes", "kube-proxy": "kubernetes", "k3s": "kubernetes", "grafana": "grafana", "grafana-server": "grafana", "prometheus": "prometheus", "jenkins": "jenkins", "vault": "vault", "consul": "consul", "nomad": "nomad", "ollama": "ollama", "mosquitto": "mosquitto", "cloudflared": "cloudflare", "tailscaled": "tailscale"};
const FRAMEWORKS = {"Vite": "vite", "Next.js": "nextjs", "Nuxt": "nuxt", "Astro": "astro", "Remix": "remix", "React Router": "remix", "SvelteKit": "svelte", "Angular": "angular", "Gatsby": "gatsby", "Docusaurus": "docusaurus", "VitePress": "vitepress", "Expo": "expo", "Electron": "electron", "NestJS": "nestjs", "Create React App": "react", "webpack": "webpack", "Express": "express", "Fastify": "fastify", "Hono": "hono", "Storybook": "storybook", "Wrangler": "cloudflareworkers", "Django": "django", "FastAPI": "fastapi", "Flask": "flask", "Gunicorn": "gunicorn", "Streamlit": "streamlit", "Jupyter": "jupyter", "Python http.server": "python", "Rails": "rails", "Jekyll": "jekyll", "Laravel": "laravel", "Symfony": "symfony", "Hugo": "hugo", "Tauri": "tauri", "Spring Boot": "spring", "Ktor": "ktor", "ASP.NET Core": "dotnet", "Phoenix": "phoenix", "Leptos": "leptos", "Actix Web": "actix"};
const LANGUAGES = {"Python": "python", "PHP": "php", "Ruby": "ruby", "Bash": "bash", "Shell": "bash", "Node.js": "nodejs", "Deno": "deno", "Bun": "bun", "Go": "go", "Rust": "rust", "Perl": "perl", "Java": "java", ".NET": "dotnet", "Elixir": "elixir", "Dart": "dart", "Kotlin": "kotlin", "Lua": "lua", "PowerShell": "powershell"};

const urls = new Map();

// logoFor picks a logo for a row: its server by process name, then its
// framework, then its language. It returns null when none fits.
export function logoFor(row) {
  const proc = (row.process || "").toLowerCase().replace(/\.exe$/, "");
  const key = PROCESSES[proc] || (proc.startsWith("postgres") ? "postgresql" : "") ||
    FRAMEWORKS[row.framework] || LANGUAGES[row.language];
  if (!key) return null;
  if (!urls.has(key)) urls.set(key, "data:image/svg+xml;charset=utf-8," + encodeURIComponent(SVG[key]));
  return { key, url: urls.get(key), dark: DARK.has(key) };
}
